     , bbs30_seq            = #{r.seq}
     , bbs30_type_cd        = #{r.typeCd}
     , bbs30_use_yn         = CASE WHEN #{r.useYn} THEN 'true' ELSE 'false' END
     , bbs30_public_yn      = CASE WHEN #{r.publicYn} THEN 'true' ELSE 'false' END
 WHERE bbs30_class_tree_id  = #{r.classTreeId}
   AND bbs30_company_id     = #{companyId}

